"""Menu recommendations generated by the vision/LLM gateway.

Given the AKG lunch target and the nutrition totals already detected on the
tray, ask the LLM what to add or swap so the meal gets closer to the target.
"""
from __future__ import annotations

from app.config import Settings
from app.schemas_api import (
    MenuRecommendationIn,
    MenuRecommendationOut,
    RecommendedMenuItemOut,
)
from app.services import llm_detector

METRIC_LABELS = [
    ("calories", "Energi", "kkal"),
    ("protein", "Protein", "g"),
    ("fat", "Lemak", "g"),
    ("carbohydrate", "Karbohidrat", "g"),
    ("fiber", "Serat", "g"),
]

_SYSTEM_PROMPT = (
    "Kamu adalah ahli gizi profesional untuk program Makan Bergizi Gratis (MBG) di Indonesia. "
    "Jawab murni HANYA dengan JSON valid tanpa markdown, tanpa prolog, tanpa epilog. "
    "Rekomendasi harus memakai bahan makanan Indonesia yang umum di menu SPPG, realistis, "
    "dan mudah diadakan."
)

_SHAPE = (
    "Ubah teks berikut menjadi satu objek JSON valid dengan bentuk "
    '{"summary": "...", "items": [...], "tips": [...]}. '
    "Setiap item memakai kunci: name, category, portion, reason, estimatedGram. "
    "category harus salah satu dari: Pokok, Lauk, Sayur, Buah, Minuman, Lainnya."
)


def _fmt(value: object) -> str:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "0"
    return f"{number:.1f}".rstrip("0").rstrip(".")


def _gap_lines(payload: MenuRecommendationIn) -> str:
    lines: list[str] = []
    for key, label, unit in METRIC_LABELS:
        target = payload.target.get(key)
        current = payload.current.get(key)
        if target is None and current is None:
            continue
        try:
            diff = float(target or 0) - float(current or 0)
        except (TypeError, ValueError):
            continue
        state = "kurang" if diff > 0 else "berlebih"
        lines.append(
            f"- {label}: target {_fmt(target)} {unit}, sudah ada {_fmt(current)} {unit} "
            f"({state} {_fmt(abs(diff))} {unit})"
        )
    return "\n".join(lines) or "- Data gizi tidak lengkap."


def _component_lines(payload: MenuRecommendationIn) -> str:
    if not payload.components:
        return "- Tidak ada komponen terdeteksi."
    lines = []
    for item in payload.components:
        lines.append(
            f"- {item.name} ({item.category}), {_fmt(item.gram)} g, "
            f"{_fmt(item.calories)} kkal, protein {_fmt(item.protein)} g, "
            f"lemak {_fmt(item.fat)} g, karbohidrat {_fmt(item.carbohydrate)} g, "
            f"serat {_fmt(item.fiber)} g"
        )
    return "\n".join(lines)


def _user_prompt(payload: MenuRecommendationIn) -> str:
    notes = (payload.notes or "").strip()
    return f"""Seorang petugas SPPG memotret satu ompreng makan siang dan hasil deteksi gizinya sudah dihitung.

KELOMPOK SASARAN: {payload.target_group or "tidak disebutkan"}

SELISIH TERHADAP TARGET AKG MAKAN SIANG:
{_gap_lines(payload)}

ISI OMPRENG SAAT INI:
{_component_lines(payload)}

CATATAN PETUGAS: {notes or "-"}

TUGAS:
1. Beri 2 sampai 4 saran penambahan atau penggantian menu yang paling berdampak untuk menutup kekurangan gizi di atas.
2. Utamakan kekurangan protein, serat, dan sayur/buah bila ada.
3. Jika suatu zat gizi justru berlebih, sarankan porsi yang lebih kecil atau penggantian, bukan penambahan.
4. Untuk setiap saran, tulis porsi yang jelas (misal "1 potong 50 g", "1 mangkuk 100 g").
5. Bagian "reason" menjelaskan singkat zat gizi apa yang diperbaiki.
6. "summary" maksimal 2 kalimat: kondisi ompreng saat ini dan arah perbaikannya.
7. "tips" berisi 2 sampai 3 tips singkat operasional untuk petugas SPPG.
8. Jangan menyarankan makanan yang sudah ada di ompreng kecuali untuk menambah porsi.

FORMAT OUTPUT:
Kembalikan HANYA JSON:
{{
  "summary": "...",
  "items": [
    {{
      "name": "Nama menu",
      "category": "Pokok|Lauk|Sayur|Buah|Minuman|Lainnya",
      "portion": "1 potong 50 g",
      "reason": "Menambah protein sekitar 10 g",
      "estimatedGram": 50
    }}
  ],
  "tips": ["...", "..."]
}}"""


async def recommend(settings: Settings, payload: MenuRecommendationIn) -> MenuRecommendationOut:
    parsed = await llm_detector.complete_json(
        settings=settings,
        system_prompt=_SYSTEM_PROMPT,
        user_prompt=_user_prompt(payload),
        required_key="items",
        shape_instruction=_SHAPE,
        temperature=0.3,
        max_tokens=2048,
    )

    items: list[RecommendedMenuItemOut] = []
    for raw in parsed.get("items") or []:
        if not isinstance(raw, dict):
            continue
        name = str(raw.get("name") or "").strip()
        if not name:
            continue
        try:
            grams = float(raw.get("estimatedGram") or raw.get("estimated_gram") or 0)
        except (TypeError, ValueError):
            grams = 0
        items.append(
            RecommendedMenuItemOut(
                name=name,
                category=str(raw.get("category") or "Lainnya").strip() or "Lainnya",
                portion=str(raw.get("portion") or "").strip(),
                reason=str(raw.get("reason") or "").strip(),
                estimated_gram=max(grams, 0),
            )
        )

    tips = [
        str(tip).strip()
        for tip in (parsed.get("tips") or [])
        if str(tip).strip()
    ]

    return MenuRecommendationOut(
        summary=str(parsed.get("summary") or "").strip(),
        items=items,
        tips=tips,
    )
